static Func<int, Task<IReadOnlyList<int>>> Api(List<int> fetched, int pages) => async page =>
{
    fetched.Add(page);
    await Task.Delay(5);
    return page <= pages ? new[] { page * 10 + 1, page * 10 + 2 } : Array.Empty<int>();
};

Test("every item, in order", () =>
{
    var fetched = new List<int>();
    var all = new List<int>();
    Task.Run(async () => { await foreach (var x in Pager.All(Api(fetched, 3))) all.Add(x); }).Wait();
    CheckEq(all, new[] { 11, 12, 21, 22, 31, 32 });
    CheckEq(fetched, new[] { 1, 2, 3, 4 });
});

Test("stopping early stops fetching", () =>
{
    var fetched = new List<int>();
    var first = new List<int>();
    Task.Run(async () =>
    {
        await foreach (var x in Pager.All(Api(fetched, 100)))
        {
            first.Add(x);
            if (first.Count == 3) break;
        }
    }).Wait();
    CheckEq(first, new[] { 11, 12, 21 });
    CheckEq(fetched, new[] { 1, 2 });
});

